-- Identity core: people, roles as permission bundles, devices and
-- device-bound sessions (ADR 0003, 0004, 0012; docs/architecture.md "Core
-- domain model").
--
-- Conventions for the core schema:
--   * Primary keys are UUIDv7 generated by PostgreSQL (uuidv7(), PostgreSQL
--     18+), so they sort by creation time.
--   * Every timestamp is timestamptz; the application reads and writes UTC.
--   * Enumerations are text with a CHECK constraint, so adding a value is a
--     constraint change rather than an enum type migration.
--   * people.id is the anchor for the rest of the directory (teams and
--     memberships, profile field values, account links), which arrive as new
--     tables referencing it.
--
-- Rows are changed only through package identity, which writes an audit entry
-- in the same transaction (see 00003_audit_entries.sql).

-- +goose Up
CREATE TABLE people (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    -- Lower case, used as the account name in managed services.
    username     text NOT NULL CHECK (username ~ '^[a-z0-9][a-z0-9._-]{0,62}$'),
    -- Stored as entered; unique case-insensitively (people_work_email_key).
    work_email   text NOT NULL CHECK (length(work_email) <= 254 AND work_email ~ '^[^@[:space:]]+@[^@[:space:]]+$'),
    display_name text NOT NULL CHECK (btrim(display_name) <> '' AND length(display_name) <= 200),
    status       text NOT NULL DEFAULT 'invited' CHECK (status IN ('invited', 'active', 'suspended', 'offboarded')),
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX people_username_key ON people (username);
CREATE UNIQUE INDEX people_work_email_key ON people (lower(work_email));

-- Roles are bundles of permissions (ADR 0004). Built-in roles (owner, admin,
-- member) are seeded on startup from package authz, the single source of
-- truth for permission names; custom presets are later rows with
-- builtin = false.
CREATE TABLE roles (
    id         uuid PRIMARY KEY DEFAULT uuidv7(),
    key        text NOT NULL UNIQUE CHECK (key ~ '^[a-z][a-z0-9_]{0,62}$'),
    -- English display name; the UI translates built-in roles by key.
    name       text NOT NULL CHECK (btrim(name) <> '' AND length(name) <= 100),
    builtin    boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Permission names are validated against the registry in Go; the database
-- only enforces their shape. Unknown names are ignored when permissions are
-- resolved.
CREATE TABLE role_permissions (
    role_id    uuid NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
    permission text NOT NULL CHECK (permission ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'),
    PRIMARY KEY (role_id, permission)
);

CREATE TABLE person_roles (
    person_id  uuid NOT NULL REFERENCES people (id) ON DELETE CASCADE,
    role_id    uuid NOT NULL REFERENCES roles (id) ON DELETE RESTRICT,
    granted_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (person_id, role_id)
);

CREATE INDEX person_roles_role_id_idx ON person_roles (role_id);

-- A device is a browser or an installed app of one person (ADR 0012). Revoking
-- a device revokes its sessions; clients wipe their app data when they see it.
CREATE TABLE devices (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    person_id    uuid NOT NULL REFERENCES people (id) ON DELETE CASCADE,
    name         text NOT NULL CHECK (btrim(name) <> '' AND length(name) <= 100),
    platform     text NOT NULL CHECK (platform IN ('web', 'ios', 'android')),
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    revoked_at   timestamptz,
    -- Target of the composite foreign key from sessions.
    UNIQUE (id, person_id)
);

CREATE INDEX devices_person_id_idx ON devices (person_id);

-- Every session is bound to a device of the same person (the composite
-- foreign key enforces it). Only a SHA-256 hash of the session token is
-- stored, never the token itself.
CREATE TABLE sessions (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    person_id    uuid NOT NULL,
    device_id    uuid NOT NULL,
    token_hash   bytea NOT NULL CHECK (octet_length(token_hash) = 32),
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    revoked_at   timestamptz,
    CHECK (expires_at > created_at),
    FOREIGN KEY (device_id, person_id) REFERENCES devices (id, person_id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX sessions_token_hash_key ON sessions (token_hash);
CREATE INDEX sessions_person_id_idx ON sessions (person_id);
CREATE INDEX sessions_device_id_idx ON sessions (device_id);

-- +goose Down
DROP TABLE sessions;
DROP TABLE devices;
DROP TABLE person_roles;
DROP TABLE role_permissions;
DROP TABLE roles;
DROP TABLE people;
